attempts.script:
# Ensure the output directory exists
if {![file exists outputs]} {
    file mkdir outputs
}

# Open the output file
set output_file "outputs/unloaded_nets.txt"
set fid [open $output_file w]

# Get all nets in the design using a filter
set all_nets [get_nets -filter "true"]

foreach net $all_nets {
    # Skip nets that are not connected to anything or have no driver
    # First, find driver pins (cell output pins)
    set driver_pins [get_pins -of_objects $net -filter "direction == output"]

    # If no driver pins, this net is not driven, so skip
    if {[llength $driver_pins] == 0} {
        continue
    }

    # Check for loads
    # Load is defined as:
    # 1. Cell input or clock pins
    # 2. Top-level output port pins

    set load_pins [list]

    # Get all pins connected to this net
    set all_pins [get_pins -of_objects $net]

    foreach pin $all_pins {
        set pin_dir [get_property $pin direction]
        if {$pin_dir == "input" || $pin_dir == "clock"} {
            lappend load_pins $pin
        }
    }

    # Check for top-level output port connections
    # Get ports connected to this net
    set ports [get_ports -of_objects $net]
    foreach port $ports {
        set port_dir [get_property $port direction]
        if {$port_dir == "output"} {
            # The port pin is connected to the net
            lappend load_pins $port
        }
    }

    # If no loads found, it's an unloaded net
    if {[llength $load_pins] == 0} {
        # Get the net name
        set net_name [get_property $net name]

        # Get one driver instance and pin
        set driver_pin [lindex $driver_pins 0]
        set driver_inst [get_property $driver_pin instance]
        set driver_pin_name [get_property $driver_pin name]

        # Format: <net_name> <driver_instance>/<driver_pin>
        puts $fid "$net_name $driver_inst/$driver_pin_name"
    }
}

close $fid

# Enforce maximum fanout of 10 on the placed design
# Exempt the clock net from fanout repair

# Identify the clock net name. 
# In OpenROAD, the clock net is often named after the clock port or defined in the design.
# Since the SDC defines a clock 'core_clock' on port 'clk', the net driving 'clk' is the clock net.
# We can get the clock net name from the design.
set clock_net [get_clocks -name core_clock -quiet]
if { [llength $clock_net] > 0 } {
    # Get the root of the clock, which is the net driving the clock port
    set clock_net_root [get_property $clock_net root]
    if { $clock_net_root != "" } {
        set clock_net_name [get_name $clock_net_root]
    } else {
        # Fallback: try to find the net connected to the clk port
        set clk_port [get_ports -quiet clk]
        if { [llength $clk_port] > 0 } {
            set clock_net_name [get_net -of_objects $clk_port]
        } else {
            set clock_net_name ""
        }
    }
} else {
    set clock_net_name ""
}

# If we couldn't identify the clock net, we rely on OpenROAD's internal logic to exempt clock nets.
# However, to be safe, we can try to exclude the net if we know its name.
# The repair_max_fanout command has an option -exempt_nets to exclude specific nets.

# Apply max fanout repair
# -max_fanout 10: Set the maximum fanout limit to 10
# -exempt_nets $clock_net_name: Exclude the clock net from repair (if identified)
# The command will insert buffers to reduce fanout violations.

if { $clock_net_name != "" } {
    repair_max_fanout -max_fanout 10 -exempt_nets $clock_net_name
} else {
    # If clock net name is not known, try to exempt by pattern or rely on default behavior.
    # OpenROAD's repair_max_fanout usually exempts clock nets automatically if they are marked as clocks.
    # We will use the default behavior which should be safe.
    repair_max_fanout -max_fanout 10
}

# Verify the design is still legal
# repair_max_fanout should maintain legality, but we can check if needed.
# No additional steps are required for legalization as the command handles it.

# Output the result to outputs/ if required, but the task only asks to enforce fanout.
# The design is now modified in memory.

# Enforce maximum fanout of 10 on the placed design
# Exempt the clock net from fanout repair

# Identify the clock net
# The clock port is 'clk'. The net driving this port is the clock net.
set clk_port [get_ports clk]
if { [llength $clk_port] == 0 } {
    puts "Warning: Clock port 'clk' not found. Proceeding without explicit clock exemption."
    set clock_net ""
} else {
    set clock_net [get_net -of_objects $clk_port]
    if { $clock_net == "" } {
        puts "Warning: Net driving clock port 'clk' not found. Proceeding without explicit clock exemption."
        set clock_net ""
    }
}

# Apply max fanout repair
# -max_fanout 10: Set the maximum fanout limit to 10
# -exempt_nets: Exclude the specified nets from fanout repair
if { $clock_net != "" } {
    repair_max_fanout -max_fanout 10 -exempt_nets $clock_net
} else {
    # If clock net is not identified, rely on default behavior which usually exempts clock nets
    repair_max_fanout -max_fanout 10
}

# The design should now be legally placed with fanout violations fixed.
# No further action is required for legalization as repair_max_fanout handles it.

# Enforce maximum fanout of 10 on the placed design
# Exempt the clock net from fanout repair

# Identify the clock net
# The clock port is 'clk'. The net driving this port is the clock net.
# We can get the net connected to the port 'clk'
set clk_port [get_ports clk]
if { [llength $clk_port] == 0 } {
    puts "Warning: Clock port 'clk' not found. Proceeding without explicit clock exemption."
    set clock_net ""
} else {
    # Get the net connected to the port
    # get_net -of_objects expects a list of objects (ports)
    set clock_net [get_net -of_objects $clk_port]
    if { $clock_net == "" } {
        puts "Warning: Net driving clock port 'clk' not found. Proceeding without explicit clock exemption."
        set clock_net ""
    }
}

# Apply max fanout repair
# -max_fanout 10: Set the maximum fanout limit to 10
# -exempt_nets: Exclude the specified nets from fanout repair
if { $clock_net != "" } {
    repair_max_fanout -max_fanout 10 -exempt_nets $clock_net
} else {
    # If clock net is not identified, rely on default behavior which usually exempts clock nets
    repair_max_fanout -max_fanout 10
}

# Enforce maximum fanout of 10 on the placed design
# Exempt the clock net from fanout repair

# Identify the clock net
# The clock port is 'clk'. The net driving this port is the clock net.
set clk_port [get_ports clk]
if { [llength $clk_port] == 0 } {
    puts "Warning: Clock port 'clk' not found. Proceeding without explicit clock exemption."
    set clock_net ""
} else {
    # Get the net connected to the port using get_nets
    set clock_net [get_nets -of_objects $clk_port]
    if { $clock_net == "" } {
        puts "Warning: Net driving clock port 'clk' not found. Proceeding without explicit clock exemption."
        set clock_net ""
    }
}

# Apply max fanout repair
# -max_fanout 10: Set the maximum fanout limit to 10
# -exempt_nets: Exclude the specified nets from fanout repair
if { $clock_net != "" } {
    repair_max_fanout -max_fanout 10 -exempt_nets $clock_net
} else {
    # If clock net is not identified, rely on default behavior which usually exempts clock nets
    repair_max_fanout -max_fanout 10
}

set all_cells [get_cells *]
set dff_instances {}
foreach cell $all_cells {
    if {[string equal [get_property $cell master_name] "DFF_X1"]} {
        lappend dff_instances $cell
    }
}

set all_instances [get_cells *]
set dff_instances {}
foreach inst $all_instances {
    set cell_name [get_property $inst cell_name]
    if {$cell_name eq "DFF_X1"} {
        lappend dff_instances $inst
    }
}
